results = []

def walk(obj, path):
    if isinstance(obj, dict):
        if 'law_text' in obj:
            # find identifying key
            idkeys = ['id','rule_id','ruleId','name','key','code','slug']
            idinfo = {}
            for k in idkeys:
                if k in obj:
